import { useNavigate } from "react-router-dom";

export default function AuthPromptDialog({ open, onClose }) {
  const navigate = useNavigate();

  if (!open) return null;

  const handleLogin = () => {
    onClose?.();
    navigate("/login");
  };

  const handleRegister = () => {
    onClose?.();
    navigate("/register");
  };

  return (
    <div className="fixed inset-0 z-50 flex items-center justify-center p-4" role="dialog" aria-modal="true">
      <div className="absolute inset-0 bg-black/50" onClick={onClose} />
      <div className="brutal-card-static p-6 z-10 w-full max-w-md">
        <div className="space-y-4">
          <h2 className="font-display font-black text-2xl">join the archive</h2>
          <p className="meta-ink">you need an account to comment, vote, or publish lore.</p>
        </div>
        <div className="mt-5 flex flex-col gap-3 sm:flex-row sm:justify-end">
          <button type="button" className="brutal-btn" onClick={onClose}>
            cancel
          </button>
          <button type="button" className="brutal-btn accent" onClick={handleLogin}>
            log in
          </button>
          <button type="button" className="brutal-btn accent" onClick={handleRegister}>
            sign up
          </button>
        </div>
      </div>
    </div>
  );
}
